package com.nequard.alerts;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="alert_rules") public class AlertRule{
@Id @GeneratedValue(strategy=GenerationType.UUID) UUID id;@Column(nullable=false) UUID organizationId;@Column(nullable=false) String name;@Column(nullable=false) String metric;@Column(nullable=false) String operator;@Column(nullable=false) Double threshold;@Column(nullable=false) Integer consecutiveFailures=1;@Column(nullable=false) String severity="WARNING";boolean enabled=true;Instant createdAt=Instant.now();
public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getMetric(){return metric;}public void setMetric(String v){metric=v;}public String getOperator(){return operator;}public void setOperator(String v){operator=v;}public Double getThreshold(){return threshold;}public void setThreshold(Double v){threshold=v;}public Integer getConsecutiveFailures(){return consecutiveFailures;}public void setConsecutiveFailures(Integer v){consecutiveFailures=v;}public String getSeverity(){return severity;}public void setSeverity(String v){severity=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public Instant getCreatedAt(){return createdAt;}}